verify.cmd:
node -e 'const fs=require("node:fs"),dir="supabase/migrations";
const declaration=/create\s+(?:or\s+replace\s+)?function\s+(?:public\.)?hunt_claim_apply\s*\(/gi;
let body="";
for(const file of fs.readdirSync(dir).filter(f=>/^\d{14}_.*\.sql$/.test(f)&&f.slice(0,14)>="20270346037000").sort()){
  const sql=fs.readFileSync(dir+"/"+file,"utf8");
  const matches=[...sql.matchAll(declaration)];
  if(matches.length)body=sql.slice(matches.at(-1).index);
}
const lock=body.search(/\bfor\s+update\b/i), stale=body.search(/\bstale_progress\b/i);
const read=fs.readFileSync("lib/hunts/claim-store.ts","utf8");
const rpc=fs.readFileSync("lib/hunts/apply-claim.ts","utf8");
const hasLockedCount=lock>=0&&stale>lock&&/\bcount\s*\([^)]*\)[\s\S]*?\bhunt_progress\b/i.test(body.slice(lock,stale));
process.exit(/\bp_expected_progress_count\s+integer\s+default\s+null\b/i.test(body)&&hasLockedCount&&/\bp_expected_progress_count\s*:/.test(rpc)&&/\bstale_progress\b/.test(read)?0:1);'
